import {
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { cn } from "@/lib/cn";
import { Badge } from "./badge.js";

/** Props accepted by Plate. */
export type PlateProps = {
  caption: ReactNode;
  image: ReactNode;
  label: string;
} & HTMLAttributes<HTMLElement>;

/** A labelled graphite illustration plate. */
export function Plate({
  caption,
  className,
  image,
  label,
  ...props
}: PlateProps) {
  return (
    <figure {...props} className={cn("caps-plate", className)}>
      <div className="caps-plate-image">{image}</div>
      <figcaption>
        <span>{label}</span>
        <span>{caption}</span>
      </figcaption>
    </figure>
  );
}

/** Props accepted by StagePlate. */
export type StagePlateProps = {
  caption: ReactNode;
  /** The live drawing: an element with the `caps-stage-plate-viewport` class. */
  children: ReactNode;
  /** How to handle the drawing, shown under the caption. */
  hint?: ReactNode;
  /** Id for the hint, so the drawing can name it with aria-describedby. */
  hintId?: string;
  label: string;
  /** A numbered key to what the drawing shows. */
  specimenKey?: ReactNode;
} & HTMLAttributes<HTMLElement>;

/**
 * A plate whose illustration is a live pixel-art stage rather than an image.
 * Its drawing reads `--specimen-ink`, `--specimen-paper` and
 * `--specimen-accent`, which follow the theme.
 */
export function StagePlate({
  caption,
  children,
  className,
  hint,
  hintId,
  label,
  specimenKey,
  ...props
}: StagePlateProps) {
  return (
    <figure {...props} className={cn("caps-stage-plate", className)}>
      {children}
      <figcaption>
        <span>{label}</span>
        <span className="caps-stage-plate-caption">{caption}</span>
      </figcaption>
      {hint ? (
        <p className="caps-stage-plate-hint" id={hintId}>
          {hint}
        </p>
      ) : null}
      {specimenKey}
    </figure>
  );
}

/** Props accepted by CompactPlate. */
export type CompactPlateProps = Omit<PlateProps, "className">;

/** A compact plate for editorial teasers. */
export function CompactPlate(props: CompactPlateProps) {
  return <Plate {...props} className="caps-compact-plate" />;
}

/** Props accepted by MarginNote. */
export type MarginNoteProps = {
  children: ReactNode;
} & HTMLAttributes<HTMLSpanElement>;

/** An inline note styled for the page margin. */
export function MarginNote({ children, className, ...props }: MarginNoteProps) {
  return (
    <span {...props} className={cn("caps-margin-note", className)}>
      {children}
    </span>
  );
}

/** Supported editorial callout kinds. */
export type CalloutKind = "lesson" | "status" | "plan" | "warning";
/** Props accepted by Callout. */
export type CalloutProps = {
  kind: CalloutKind;
  title?: ReactNode;
  children: ReactNode;
} & HTMLAttributes<HTMLElement>;

/** A labelled editorial aside. */
export function Callout({
  children,
  className,
  kind,
  title,
  ...props
}: CalloutProps) {
  return (
    <aside
      {...props}
      className={cn("caps-callout", className)}
      data-kind={kind}
    >
      {title ? <h2>{title}</h2> : null}
      {children}
    </aside>
  );
}

/** Supported lifecycle stages. */
export type GrowthStage = "spore" | "mycelium" | "fruiting";
/** Props accepted by GrowthBadge. */
export type GrowthBadgeProps = {
  stage: GrowthStage;
} & HTMLAttributes<HTMLSpanElement>;

/** An outlined Badge in the selected growth-stage color. */
export function GrowthBadge({ className, stage, ...props }: GrowthBadgeProps) {
  const tone =
    stage === "spore"
      ? "secondary"
      : stage === "mycelium"
        ? "primary"
        : "accent";
  return (
    <Badge
      {...props}
      className={cn("caps-growth-badge badge-outline", className)}
      data-stage={stage}
      size="sm"
      tone={tone}
    >
      {stage}
    </Badge>
  );
}

/** Props accepted by IssueMasthead. */
export type IssueMastheadProps = {
  date: string;
  dek: ReactNode;
  number: string;
  /** The publication the Issue belongs to, printed in the kicker. */
  publication: string;
  title: string;
} & HTMLAttributes<HTMLElement>;

/** The title, number, date, and dek for an Issue. */
export function IssueMasthead({
  className,
  date,
  dek,
  number,
  publication,
  title,
  ...props
}: IssueMastheadProps) {
  return (
    <header {...props} className={cn("caps-issue-masthead", className)}>
      <p className="caps-issue-kicker">
        {publication} · Issue {number} · {date}
      </p>
      <h1>{title}</h1>
      <p>{dek}</p>
    </header>
  );
}

/** A newspaper nameplate: the front page's large head or a running head. */
export type MastheadSize = "front" | "running";
/** Props accepted by Masthead. */
export type MastheadProps = {
  /** The publication name, set large in the nameplate face. */
  wordmark: string;
  /** Where the nameplate links, normally the front page. */
  href: string;
  /** A small printed mark beside the wordmark, such as a logo drawing. */
  mark?: ReactNode;
  /** One line under the wordmark in the publication's voice. */
  tagline?: ReactNode;
  /** The ruled edition line: date, issue, editor and similar items. */
  edition?: readonly ReactNode[];
  /** The left ear box beside the nameplate, such as a weather note. */
  startEar?: ReactNode;
  /** The right ear box beside the nameplate, such as the editor's portrait. */
  endEar?: ReactNode;
  /** The section bar under the edition line, normally a SectionBar. */
  sections?: ReactNode;
  size?: MastheadSize;
} & HTMLAttributes<HTMLElement>;

/**
 * A print masthead. Ears flank the nameplate on wide pages and sit under it
 * on phones; the edition line runs between a thin and a heavy rule.
 */
export function Masthead({
  className,
  edition,
  endEar,
  href,
  mark,
  sections,
  size = "front",
  startEar,
  tagline,
  wordmark,
  ...props
}: MastheadProps) {
  return (
    <header
      {...props}
      className={cn("caps-masthead", className)}
      data-size={size}
    >
      <div className="caps-masthead-plate">
        {startEar ? (
          <div className="caps-masthead-ear" data-side="start">
            {startEar}
          </div>
        ) : null}
        <a className="caps-masthead-nameplate" href={href}>
          {mark ? (
            <span aria-hidden="true" className="caps-masthead-mark">
              {mark}
            </span>
          ) : null}
          <span className="caps-masthead-wordmark">{wordmark}</span>
        </a>
        {endEar ? (
          <div className="caps-masthead-ear" data-side="end">
            {endEar}
          </div>
        ) : null}
      </div>
      {tagline ? <p className="caps-masthead-tagline">{tagline}</p> : null}
      {edition && edition.length > 0 ? (
        <ul className="caps-masthead-edition">
          {edition.map((item, index) => (
            <li key={index}>{item}</li>
          ))}
        </ul>
      ) : null}
      {sections}
    </header>
  );
}

/** One section of a publication. */
export type SectionLink = {
  href: string;
  label: string;
  /** Printed before the label, such as a section letter. */
  marker?: string;
  current?: boolean;
  /** A keyboard shortcut announced through aria-keyshortcuts. */
  shortcut?: string;
};
/** Props accepted by SectionBar. */
export type SectionBarProps = {
  sections: readonly SectionLink[];
  /** Controls set at the end of the bar, such as theme and help buttons. */
  tools?: ReactNode;
} & HTMLAttributes<HTMLElement>;

/**
 * A newspaper section bar: small capitals between hairline rules, the
 * current section printed in reverse. It scrolls sideways on narrow pages
 * instead of wrapping. Name it with aria-label.
 */
export function SectionBar({
  className,
  sections,
  tools,
  ...props
}: SectionBarProps) {
  return (
    <nav {...props} className={cn("caps-section-bar", className)}>
      <ul>
        {sections.map((section) => (
          <li key={section.href}>
            <a
              aria-current={section.current ? "page" : undefined}
              aria-keyshortcuts={section.shortcut}
              className="caps-section-bar-link"
              href={section.href}
            >
              {section.marker ? (
                <span aria-hidden="true" className="caps-section-bar-marker">
                  {section.marker}
                </span>
              ) : null}
              <span>{section.label}</span>
            </a>
          </li>
        ))}
      </ul>
      {tools ? <div className="caps-section-bar-tools">{tools}</div> : null}
    </nav>
  );
}

/** Props accepted by Folio. */
export type FolioProps = {
  /** Running items, such as the publication, page number and date. */
  items: readonly ReactNode[];
} & HTMLAttributes<HTMLElement>;

/** A running foot: the page's folio line between rules. */
export function Folio({ className, items, ...props }: FolioProps) {
  return (
    <footer {...props} className={cn("caps-folio", className)}>
      <ul>
        {items.map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
    </footer>
  );
}

/** Supported editorial spread arrangements. */
export type SpreadLayout = "lead" | "columns" | "grid";
/** Props accepted by Spread. */
export type SpreadProps = {
  layout: SpreadLayout;
  children: ReactNode;
} & HTMLAttributes<HTMLElement>;

/** A responsive editorial region with an explicit layout. */
export function Spread({ children, className, layout, ...props }: SpreadProps) {
  return (
    <section
      {...props}
      className={cn("caps-spread", className)}
      data-layout={layout}
    >
      {children}
    </section>
  );
}

/** One supplied card measurement and its provenance. `null` means not measured. */
export type CardStat = {
  key: string;
  label: string;
  value: string | number | null;
  unit?: string;
  source: string;
  asOf: string;
};
/** Print finish: the rarer full-art card lets the drawing run under the text. */
export type CigaretteCardFinish = "standard" | "full-art";
/** Props accepted by CigaretteCard. */
export type CigaretteCardProps = {
  number: number;
  /** The series numeral printed on both faces and in the series mark, such as "I". */
  seriesNumeral: string;
  series: string;
  title: string;
  /** The type line beside the title, such as "Machine of the Burrow". */
  typeLine?: string | undefined;
  image: ReactNode;
  stats: readonly CardStat[];
  note: string;
  finish?: CigaretteCardFinish;
  /** A small set symbol printed in the collector line. */
  setMark?: ReactNode;
  defaultFlipped?: boolean;
  /**
   * Makes the card a preview: a link to the card's own page showing its
   * face, instead of a pressed button that turns over in place.
   */
  href?: string;
  /** "large" prints the card bigger, for its own page. */
  size?: "standard" | "large";
  className?: string;
  /** Inline style on the card, such as a shared view-transition name. */
  style?: CSSProperties;
};

/** Print an observation date as a calendar day when it carries a time. */
function calendarDay(asOf: string): string {
  return /^\d{4}-\d{2}-\d{2}T/.test(asOf) ? asOf.slice(0, 10) : asOf;
}

function groupCardSources(stats: readonly CardStat[]) {
  const grouped = new Map<string, Set<string>>();
  for (const { source, asOf } of stats) {
    const dates = grouped.get(source) ?? new Set<string>();
    dates.add(calendarDay(asOf));
    grouped.set(source, dates);
  }
  return Array.from(grouped, ([source, dates]) => ({
    source,
    asOf: Array.from(dates),
  }));
}

function StatFigure({ stat }: { stat: CardStat }) {
  if (stat.value === null)
    return (
      <span className="caps-cigarette-card-not-measured">not measured</span>
    );
  return (
    <>
      <span className="caps-cigarette-card-numeral">{String(stat.value)}</span>
      {stat.unit ? (
        <span className="caps-cigarette-card-unit">{stat.unit}</span>
      ) : null}
    </>
  );
}

function CardHead({
  seriesNumeral,
  title,
  typeLine,
}: Pick<CigaretteCardProps, "seriesNumeral" | "title" | "typeLine">) {
  return (
    <>
      <span className="caps-cigarette-card-head">
        <span className="caps-cigarette-card-title">{title}</span>
        {typeLine ? (
          <span className="caps-cigarette-card-type">{typeLine}</span>
        ) : null}
      </span>
      <span aria-hidden="true" className="caps-cigarette-card-mark">
        <span>{seriesNumeral}</span>
      </span>
    </>
  );
}

function CollectorLine({
  number,
  series,
  seriesNumeral,
  setMark,
}: Pick<
  CigaretteCardProps,
  "number" | "series" | "seriesNumeral" | "setMark"
>) {
  return (
    <span className="caps-cigarette-card-collector">
      <span>
        No. {number} · Series {seriesNumeral}: {series}
      </span>
      {setMark ? (
        <span aria-hidden="true" className="caps-cigarette-card-set">
          {setMark}
        </span>
      ) : null}
    </span>
  );
}

/**
 * A two-sided collector card: a framed front with an inset drawing, a stat
 * plate and a flavor line, and a ruled measurement ledger on the back. Both
 * faces live inside one native pressed button, so the reverse stays in the
 * DOM; the visible face names the button. Hydrated hosts flip through React
 * state. Static hosts load the Caps `enhance/cigarette-card` module, which
 * ignores clicks this component already handled. With `href` the card is a
 * preview instead: a link to the card's own page that shows only its face.
 */
export function CigaretteCard({
  className,
  defaultFlipped = false,
  finish = "standard",
  href,
  image,
  note,
  number,
  series,
  seriesNumeral,
  setMark,
  size = "standard",
  stats,
  style,
  title,
  typeLine,
}: CigaretteCardProps) {
  const [flipped, setFlipped] = useState(defaultFlipped);
  const sources = groupCardSources(stats);
  const headline = stats.find((stat) => stat.value !== null) ?? stats[0];
  const others = stats.filter((stat) => stat !== headline).slice(0, 2);
  const head = { seriesNumeral, title, typeLine };
  const collector = { number, series, seriesNumeral, setMark };
  const front = (
    <span
      className="caps-cigarette-card-face caps-cigarette-card-front"
      aria-hidden={href ? undefined : flipped}
    >
      <CardHead {...head} />
      <span className="caps-cigarette-card-window">{image}</span>
      {headline ? (
        <span className="caps-cigarette-card-plate">
          <span className="caps-cigarette-card-headline">
            <span className="caps-cigarette-card-label">{headline.label}</span>
            <span className="caps-cigarette-card-figure">
              <StatFigure stat={headline} />
            </span>
          </span>
          {others.length > 0 ? (
            <span className="caps-cigarette-card-plate-list">
              {others.map((stat) => (
                <span key={stat.key}>
                  <span className="caps-cigarette-card-label">
                    {stat.label}
                  </span>
                  <span>
                    <StatFigure stat={stat} />
                  </span>
                </span>
              ))}
            </span>
          ) : null}
        </span>
      ) : null}
      <span className="caps-cigarette-card-flavor">{note}</span>
      <CollectorLine {...collector} />
    </span>
  );
  const back = (
    <span
      className="caps-cigarette-card-face caps-cigarette-card-back"
      aria-hidden={!flipped}
    >
      <CardHead {...head} />
      <span className="caps-cigarette-card-ledger">
        <span className="caps-cigarette-card-ledger-title">
          Field measurements
        </span>
        <span className="caps-cigarette-card-stats">
          {stats.map((stat) => (
            <span className="caps-cigarette-card-stat" key={stat.key}>
              <span className="caps-cigarette-card-stat-label">
                {stat.label}
              </span>
              <span aria-hidden="true" className="caps-cigarette-card-leader" />
              <span className="caps-cigarette-card-stat-value">
                <StatFigure stat={stat} />
              </span>
            </span>
          ))}
        </span>
        <span aria-hidden="true" className="caps-cigarette-card-cameo">
          {image}
        </span>
        <span className="caps-cigarette-card-note">{note}</span>
        <span className="caps-cigarette-card-sources">
          {sources.map(({ source, asOf }) => (
            <span className="caps-cigarette-card-source" key={source}>
              {source} · {asOf.join(", ")}
            </span>
          ))}
        </span>
      </span>
      <CollectorLine {...collector} />
    </span>
  );
  if (href)
    return (
      <a
        className={cn("caps-cigarette-card", className)}
        data-finish={finish}
        data-flipped={false}
        data-size={size}
        href={href}
        style={style}
      >
        <span className="caps-cigarette-card-inner">{front}</span>
      </a>
    );
  return (
    <button
      type="button"
      aria-pressed={flipped}
      className={cn("caps-cigarette-card", className)}
      onClick={(event) => {
        event.preventDefault();
        setFlipped((current) => !current);
      }}
      data-finish={finish}
      data-flipped={flipped}
      data-size={size}
      style={style}
    >
      <span className="caps-cigarette-card-inner">
        {front}
        {back}
      </span>
    </button>
  );
}

/** One numbered album position, optionally occupied by a card. */
export type AlbumSlot = { number: number; card?: CigaretteCardProps };
/** Props accepted by CardAlbum. */
export type CardAlbumProps = {
  title: string;
  slots: readonly AlbumSlot[];
} & HTMLAttributes<HTMLElement>;

/** A numbered checklist of supplied cards and ruled spaces for missing ones. */
export function CardAlbum({
  className,
  slots,
  title,
  ...props
}: CardAlbumProps) {
  const collected = slots.filter((slot) => slot.card !== undefined).length;
  return (
    <section {...props} className={cn("caps-album", className)}>
      <header className="caps-album-head">
        <h2>{title}</h2>
        <p>
          {collected} of {slots.length} collected
        </p>
      </header>
      <ol>
        {slots.map(({ card, number }) => (
          <li key={number} data-collected={card !== undefined}>
            {card ? (
              <CigaretteCard {...card} />
            ) : (
              <span className="caps-album-empty">
                <span>No. {number}</span>
                <span>not yet collected</span>
              </span>
            )}
          </li>
        ))}
      </ol>
    </section>
  );
}

import type { HTMLAttributes, ReactNode } from "react";

import { cn } from "@/lib/cn";

/** A visible keyboard key from a shortcut or instruction. */
export type KeycapProps = {
  children: ReactNode;
} & HTMLAttributes<HTMLElement>;

/** The shared field-guide treatment for a keyboard key. */
export function Keycap({ children, className, ...props }: KeycapProps) {
  return (
    <kbd {...props} className={cn("caps-keycap", className)}>
      {children}
    </kbd>
  );
}

/** Semantic accent pigments for the static status light. */
export type StatusLedTone = "spore" | "mycelium" | "fruiting";
/** Props accepted by StatusLed. */
export type StatusLedProps = {
  active: boolean;
  label: string;
  tone?: StatusLedTone;
} & Omit<HTMLAttributes<HTMLSpanElement>, "children">;

/** A static, labelled indicator using the current field-guide pigment tokens. */
export function StatusLed({
  active,
  className,
  label,
  tone = "mycelium",
  ...props
}: StatusLedProps) {
  return (
    <span
      {...props}
      aria-label={`${label}: ${active ? "on" : "off"}`}
      className={cn("caps-led", className)}
      data-active={active}
      data-tone={tone}
      role="img"
    >
      <span aria-hidden="true" className="caps-led-bead" />
      <span aria-hidden="true">{label}</span>
    </span>
  );
}

/** Props accepted by CartridgeLabel. */
export type CartridgeLabelProps = {
  title: string;
  subtitle?: string;
  mark?: ReactNode;
} & HTMLAttributes<HTMLElement>;

/** A ruled, token-backed printed label for a physical game cartridge. */
export function CartridgeLabel({
  className,
  mark,
  subtitle,
  title,
  ...props
}: CartridgeLabelProps) {
  return (
    <figure
      {...props}
      aria-label={`${title} cartridge label`}
      className={cn("caps-cartridge-label", className)}
    >
      <span aria-hidden="true" className="caps-cartridge-label-rule" />
      {mark ? (
        <span aria-hidden="true" className="caps-cartridge-label-mark">
          {mark}
        </span>
      ) : null}
      <span className="caps-cartridge-label-title">{title}</span>
      {subtitle ? (
        <span className="caps-cartridge-label-subtitle">{subtitle}</span>
      ) : null}
      <span aria-hidden="true" className="caps-cartridge-label-rule" />
    </figure>
  );
}

/** Props accepted by SpecimenLabel. */
export type SpecimenLabelProps = {
  plate: string;
  detail: string;
  kind: string;
  number: string;
  title: ReactNode;
  summary?: ReactNode;
  /**
   * Mark the plate number for a pencil circle and the detail for a pencil
   * underline. The ruled CSS marks remain until `enhance/sketch` draws them.
   */
  sketch?: boolean;
} & Omit<HTMLAttributes<HTMLElement>, "title">;

/** A caption, catalogue line, title, and note for a specimen illustration. */
export function SpecimenLabel({
  className,
  detail,
  kind,
  number,
  plate,
  sketch = false,
  summary,
  title,
  ...props
}: SpecimenLabelProps) {
  return (
    <aside {...props} className={cn("caps-specimen-label", className)}>
      <p className="caps-specimen-label-caption">
        <span
          className="caps-specimen-label-plate"
          data-sketch={sketch ? "circle" : undefined}
        >
          {plate}
        </span>
        <span
          className="caps-specimen-label-detail"
          data-sketch={sketch ? "underline" : undefined}
        >
          {detail}
        </span>
      </p>
      <span className="caps-specimen-label-meta">
        {kind} · {number}
      </span>
      <div className="caps-specimen-label-title">{title}</div>
      {summary ? (
        <p className="caps-specimen-label-summary">{summary}</p>
      ) : null}
    </aside>
  );
}

import { forwardRef, type HTMLAttributes } from "react";

import { cn, cva } from "@/lib/cn";

/** Supported BadgeTone values. */
export type BadgeTone =
  | "neutral"
  | "primary"
  | "secondary"
  | "accent"
  | "success"
  | "info"
  | "warning"
  | "error";
/** Supported BadgeSize values. */
export type BadgeSize = "sm" | "default" | "lg";
/** `quiet` is a soft tint with no outline, for labels that sit beside keys. */
export type BadgeVariant = "solid" | "quiet";

const badgeVariants = cva("badge caps-badge", {
  variants: {
    tone: {
      neutral: "badge-neutral",
      primary: "badge-primary",
      secondary: "badge-secondary",
      accent: "badge-accent",
      success: "badge-success",
      info: "badge-info",
      warning: "badge-warning",
      error: "badge-error",
    },
    size: { sm: "badge-sm", default: "badge-md", lg: "badge-lg" },
    variant: { solid: "", quiet: "caps-badge-quiet" },
  },
  defaultVariants: { tone: "neutral", size: "default" },
});

/** Props accepted by Badge. */
export type BadgeProps = {
  size?: BadgeSize;
  variant?: BadgeVariant;
  tone?: BadgeTone;
} & HTMLAttributes<HTMLSpanElement>;

/** A compact status or category label. */
export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { className, size, tone, variant, ...props },
  ref,
) {
  return (
    <span
      {...props}
      className={cn(badgeVariants({ size, tone, variant }), className)}
      ref={ref}
    />
  );
});

import { forwardRef, type HTMLAttributes } from "react";

import { cn } from "@/lib/cn";

/** Supported Prose treatments. */
export type ProseVariant = "default" | "dropcap";
/** Props accepted by Prose. */
export type ProseProps = {
  variant?: ProseVariant;
} & HTMLAttributes<HTMLElement>;

/**
 * Tailwind Typography's `prose` rhythm and measure in the active theme's
 * colours and faces; the caller supplies the document content.
 */
export const Prose = forwardRef<HTMLElement, ProseProps>(function Prose(
  { className, variant = "default", ...props },
  ref,
) {
  return (
    <article
      {...props}
      className={cn(
        "prose prose-caps",
        variant === "dropcap" && "caps-prose-dropcap",
        className,
      )}
      ref={ref}
    />
  );
});

import roughImport from "roughjs";
import type { RoughSVG } from "roughjs/bin/svg.js";

type RoughSvg = RoughSVG;
type RoughOptions = NonNullable<Parameters<RoughSvg["line"]>[4]>;
type RoughApi = { svg(svg: SVGSVGElement): RoughSvg };

// roughjs ships CommonJS types beside an ESM `module` build: NodeNext sees the
// API under `default`, bundlers hand over the API itself. Accept either.
type RoughEntry = RoughApi | { readonly default: RoughApi };

function resolveRough(entry: RoughEntry): RoughApi {
  return "svg" in entry ? entry : entry.default;
}

const rough = resolveRough(roughImport);

const SVG = "http://www.w3.org/2000/svg";

/**
 * The opt-in pencil layer for server-rendered field-guide pages.
 *
 * Markup contract, all plain attributes so any host can use it without React:
 * - `data-sketch-root` marks a positioned host; its overlay is drawn inside it.
 * - `data-sketch="circle" | "underline"` marks inline text to annotate.
 * - `data-sketch-leader-x` / `data-sketch-leader-y` (fractions of the target
 *   box) on a note draw a leader from the note to the `data-sketch-target`
 *   inside the same `data-sketch-item`. The layout decides whether leaders
 *   apply by setting `--caps-sketch-leader: on` on the note.
 *
 * Strokes use `currentColor`, so a theme switch recolors them without a
 * redraw. The host receives `data-sketch-drawn` once annotations exist, which
 * lets Caps hide the static CSS fallbacks they replace.
 */
export function sketch(root: ParentNode = document): () => void {
  const hosts = Array.from(
    root.querySelectorAll<HTMLElement>("[data-sketch-root]"),
  );
  const draw = () => {
    for (const [index, host] of hosts.entries()) drawHost(host, index);
  };
  draw();
  // Older engines and jsdom lack ResizeObserver; they draw once.
  const observer =
    "ResizeObserver" in globalThis ? new ResizeObserver(draw) : undefined;
  for (const host of hosts) observer?.observe(host);
  // Web fonts move annotated text once they load; jsdom has no font set.
  if ("fonts" in document) void document.fonts.ready.then(draw);
  return () => {
    observer?.disconnect();
    for (const host of hosts) {
      host.querySelector(":scope > .caps-sketch-overlay")?.remove();
      delete host.dataset.sketchDrawn;
    }
  };
}

function drawHost(host: HTMLElement, index: number): void {
  host.querySelector(":scope > .caps-sketch-overlay")?.remove();
  const bounds = host.getBoundingClientRect();
  if (!bounds.width || !bounds.height) return;

  const overlay = document.createElementNS(SVG, "svg");
  overlay.setAttribute(
    "viewBox",
    `0 0 ${String(bounds.width)} ${String(bounds.height)}`,
  );
  overlay.setAttribute("aria-hidden", "true");
  overlay.setAttribute("focusable", "false");
  overlay.classList.add("caps-sketch-overlay");
  const generator = rough.svg(overlay);

  for (const [markIndex, mark] of host
    .querySelectorAll<HTMLElement>("[data-sketch]")
    .entries()) {
    const annotation = drawMark(generator, bounds, mark, {
      roughness: 1.1,
      stroke: "currentColor",
      strokeWidth: 1.3,
      seed: 2601 + index * 10 + markIndex,
    });
    if (annotation) overlay.append(annotation);
  }
  for (const [noteIndex, note] of host
    .querySelectorAll<HTMLElement>("[data-sketch-leader-x]")
    .entries()) {
    const leader = drawLeader(generator, bounds, note, {
      roughness: 1.2,
      stroke: "currentColor",
      strokeWidth: 1.2,
      seed: 3101 + index * 10 + noteIndex,
    });
    if (leader) overlay.append(leader);
  }
  host.append(overlay);
  host.dataset.sketchDrawn = "";
}

function drawMark(
  generator: RoughSvg,
  host: DOMRect,
  mark: HTMLElement,
  options: RoughOptions,
): SVGGElement | undefined {
  const box = mark.getBoundingClientRect();
  if (!box.width || !box.height) return undefined;
  const x = box.left - host.left;
  const y = box.top - host.top;
  switch (mark.dataset.sketch) {
    case "circle":
      return generator.ellipse(
        x + box.width / 2,
        y + box.height / 2,
        box.width + 9,
        box.height + 7,
        options,
      );
    case "underline":
      return generator.line(
        x,
        y + box.height + 3,
        x + box.width,
        y + box.height + 3,
        options,
      );
    default:
      return undefined;
  }
}

function drawLeader(
  generator: RoughSvg,
  host: DOMRect,
  note: HTMLElement,
  options: RoughOptions,
): SVGGElement | undefined {
  if (
    getComputedStyle(note).getPropertyValue("--caps-sketch-leader").trim() !==
    "on"
  )
    return undefined;
  const target = note
    .closest("[data-sketch-item]")
    ?.querySelector<HTMLElement>("[data-sketch-target]");
  const fx = Number(note.dataset.sketchLeaderX);
  const fy = Number(note.dataset.sketchLeaderY);
  if (!target || !Number.isFinite(fx) || !Number.isFinite(fy)) return undefined;

  const targetBox = target.getBoundingClientRect();
  const noteBox = note.getBoundingClientRect();
  const endX = targetBox.left - host.left + targetBox.width * fx;
  const endY = targetBox.top - host.top + targetBox.height * fy;
  const startX = Math.min(
    Math.max(endX, noteBox.left - host.left + 18),
    noteBox.right - host.left - 18,
  );
  const startY = noteBox.top - host.top - 8;
  const length = Math.hypot(endX - startX, endY - startY);
  if (length < 12) return undefined;

  const group = document.createElementNS(SVG, "g");
  const bend = Math.min(16, length / 10);
  group.append(
    generator.curve(
      [
        [startX, startY],
        [(startX + endX) / 2 + bend, (startY + endY) / 2],
        [endX, endY],
      ],
      options,
    ),
  );
  const angle = Math.atan2(endY - startY, endX - startX);
  for (const side of [-1, 1]) {
    const wing = angle + Math.PI + side * 0.45;
    group.append(
      generator.line(
        endX,
        endY,
        endX + Math.cos(wing) * 11,
        endY + Math.sin(wing) * 11,
        options,
      ),
    );
  }
  return group;
}

/** Only the pressed-button card turns over; a preview card is a link. */
const CARD = "button.caps-cigarette-card";

/** Show one face of a server-rendered CigaretteCard. */
export function setCigaretteCardFlipped(
  card: HTMLElement,
  flipped: boolean,
): void {
  card.setAttribute("aria-pressed", String(flipped));
  card.dataset.flipped = String(flipped);
  card
    .querySelector(".caps-cigarette-card-front")
    ?.setAttribute("aria-hidden", String(flipped));
  card
    .querySelector(".caps-cigarette-card-back")
    ?.setAttribute("aria-hidden", String(!flipped));
}

function onClick(event: Event): void {
  // A hydrated CigaretteCard handles its own click and marks it prevented.
  if (event.defaultPrevented || !(event.target instanceof Element)) return;
  const card = event.target.closest<HTMLElement>(CARD);
  if (!card) return;
  setCigaretteCardFlipped(card, card.getAttribute("aria-pressed") !== "true");
}

/**
 * Flip server-rendered CigaretteCards on click, tap, Enter or Space. The card
 * is a native button, so the keyboard reaches it as a click; this only
 * toggles the pressed state. Returns a cleanup that removes the listener.
 */
export function enhanceCigaretteCards(
  root: Document | HTMLElement = document,
): () => void {
  root.addEventListener("click", onClick);
  return () => {
    root.removeEventListener("click", onClick);
  };
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

